package com.lue.erp.orders;
import com.lue.erp.auth.AuthService;import com.lue.erp.auth.AuthUser;import com.lue.erp.common.api.ApiResponse;import com.lue.erp.profits.ProfitCalculationService;import jakarta.servlet.http.HttpServletRequest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api/exceptions") public class ExceptionController {
 private final JdbcTemplate db;private final AuthService auth;private final ProfitCalculationService profits;public ExceptionController(JdbcTemplate db,AuthService auth,ProfitCalculationService profits){this.db=db;this.auth=auth;this.profits=profits;}
 @GetMapping public ApiResponse<Map<String,Object>> list(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int pageSize,@RequestParam(defaultValue="OPEN")String status,@AuthenticationPrincipal AuthUser u){view(u);int p=Math.max(page,1),s=Math.min(100,Math.max(1,pageSize));Long total=db.queryForObject("SELECT COUNT(*) FROM exceptions WHERE status=?",Long.class,status);List<Map<String,Object>>items=db.queryForList("SELECT e.id,e.exception_no exceptionNo,e.exception_type exceptionType,e.status,e.shop_id shopId,sh.shop_name shopName,e.platform_sku platformSku,e.order_summary_id orderSummaryId,e.fulfillment_item_id fulfillmentItemId,e.raw_data rawData,e.title,e.created_at createdAt,d.document_no documentNo,d.source_document_id sourceDocumentId FROM exceptions e LEFT JOIN shops sh ON sh.id=e.shop_id LEFT JOIN fulfillment_document_items fi ON fi.id=e.fulfillment_item_id LEFT JOIN fulfillment_documents d ON d.id=COALESCE(e.fulfillment_document_id,fi.document_id) WHERE e.status=? ORDER BY e.id DESC LIMIT ? OFFSET ?",status,s,(p-1)*s);return ApiResponse.ok(Map.of("items",items,"total",total==null?0:total,"page",p,"pageSize",s));}
 @Transactional @PostMapping("/{id}/map") public ApiResponse<Map<String,Object>> map(@PathVariable long id,@RequestBody Map<String,Object>b,@AuthenticationPrincipal AuthUser u,HttpServletRequest req){view(u);auth.requirePermission(u.id(),"master.data.manage");Map<String,Object>e=db.queryForMap("SELECT shop_id shopId,platform_sku platformSku,order_summary_id orderId,fulfillment_item_id fulfillmentItemId,exception_type exceptionType,status FROM exceptions WHERE id=?",id);if(!"OPEN".equals(e.get("status")))throw new IllegalArgumentException("异常已处理");long skuId=Long.parseLong(String.valueOf(b.get("skuId")));Integer valid=db.queryForObject("SELECT COUNT(*) FROM skus WHERE id=? AND status='ACTIVE' AND is_deleted=FALSE",Integer.class,skuId);if(valid==null||valid==0)throw new IllegalArgumentException("请选择有效内部 SKU");Long mapping=db.query("SELECT id FROM shop_sku_mappings WHERE shop_id=? AND platform_sku=? AND status='ACTIVE' AND is_deleted=FALSE",rs->rs.next()?rs.getLong(1):null,e.get("shopId"),e.get("platformSku"));if(e.get("shopId")!=null){if(mapping==null)db.update("INSERT INTO shop_sku_mappings(shop_id,platform_sku,sku_id,default_order_mode,status) VALUES (?,?,?,?,'ACTIVE')",e.get("shopId"),e.get("platformSku"),skuId,b.getOrDefault("defaultOrderMode","JIT"));else db.update("UPDATE shop_sku_mappings SET sku_id=? WHERE id=?",skuId,mapping);}int recalculated=0;if("FULFILLMENT_SKU_UNMATCHED".equals(e.get("exceptionType"))&&e.get("fulfillmentItemId")!=null){recalculated=db.update("UPDATE fulfillment_document_items SET sku_id=? WHERE id=? AND sku_id IS NULL",skuId,e.get("fulfillmentItemId"));db.update("UPDATE fulfillment_documents d SET local_status=CASE WHEN EXISTS(SELECT 1 FROM fulfillment_document_items i WHERE i.document_id=d.id AND i.sku_id IS NULL) THEN 'SKU_UNMATCHED' ELSE 'READY_TO_PICK' END WHERE d.id=(SELECT document_id FROM fulfillment_document_items WHERE id=?) AND d.local_status='SKU_UNMATCHED'",e.get("fulfillmentItemId"));}else if(e.get("orderId")!=null){recalculated=db.update("UPDATE order_summaries SET sku_id=? WHERE shop_id=? AND platform_sku=? AND sku_id IS NULL AND is_deleted=FALSE",skuId,e.get("shopId"),e.get("platformSku"));if(recalculated>0){var range=db.queryForMap("SELECT MIN(order_date) minDate,MAX(order_date) maxDate FROM order_summaries WHERE shop_id=? AND platform_sku=? AND sku_id=? AND is_deleted=FALSE",e.get("shopId"),e.get("platformSku"),skuId);Object min=range.get("minDate"),max=range.get("maxDate");if(min!=null&&max!=null)profits.recalculate(((java.sql.Date)min).toLocalDate(),((java.sql.Date)max).toLocalDate());}}db.update("UPDATE exceptions SET status='RESOLVED',resolution_note=CONCAT('已补充店铺 SKU 映射并重新匹配 ',?,' 条记录'),resolved_at=CURRENT_TIMESTAMP WHERE id=?",recalculated,id);db.update("INSERT INTO operation_logs(user_id,username,action,resource_type,resource_id,detail,ip_address,success) VALUES (?,?,'fulfillment.exception.map','exception',?,JSON_OBJECT('skuId',?,'recalculatedRows',?),?,TRUE)",u.id(),u.username(),String.valueOf(id),skuId,recalculated,req.getRemoteAddr());return ApiResponse.ok(Map.of("recalculatedRows",recalculated,"resolved",true));}
 private void view(AuthUser u){auth.requirePermission(u.id(),"menu.imports");}
}
